export function ActivityLog({
  heading = "{{heading}}",
  entries = "{{entries}}",
  density = "{{density}}",
  accent = "{{accent}}",
  showIcons = {{showIcons}},
}) {
  const items = [
    { text: "You uploaded a file", target: '"roadmap.pdf"', time: "2026-08-18T07:15:00Z", label: "2 hours ago" },
    { text: "You updated the", target: '"Billing" settings', time: "2026-08-18T04:20:00Z", label: "5 hours ago" },
    { text: "You invited", target: "teammate@example.com", time: "2026-08-17T09:10:00Z", label: "1 day ago" },
    { text: "You archived project", target: '"Legacy API"', time: "2026-08-16T09:10:00Z", label: "2 days ago" },
    { text: "You changed your password", target: null, time: "2026-08-14T09:10:00Z", label: "4 days ago" },
  ].slice(0, Number(entries));
  const pad = density === "compact" ? "4px 0" : "8px 0";
  const fontSize = density === "compact" ? 12.5 : 13.5;
  return (
    <section style={{ fontFamily: "system-ui, sans-serif", fontSize: 13.5, lineHeight: 1.5, color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, maxWidth: 360, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 10px", fontSize: 14, fontWeight: 600, textTransform: "uppercase", letterSpacing: ".03em", color: "#24143099" }}>{heading}</h3>
      <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
        {items.map((item, i) => (
          <li key={item.time} style={{ display: "flex", alignItems: "baseline", gap: 8, padding: pad, fontSize,
            borderBottom: i < items.length - 1 ? "1px solid #24143014" : "none" }}>
            {showIcons && <span aria-hidden="true" style={{ flex: "none", width: 7, height: 7, borderRadius: "50%", background: accent }} />}
            <p style={{ margin: 0, flex: 1 }}>{item.text}{item.target ? <> <strong style={{ fontWeight: 600 }}>{item.target}</strong></> : null}</p>
            <time dateTime={item.time} style={{ flex: "none", fontSize: 12, color: "#24143099", whiteSpace: "nowrap" }}>{item.label}</time>
          </li>
        ))}
      </ul>
    </section>
  );
}
